// =====================================================
//  BOT UYAY – edita textos y datos en esta sección
// =====================================================
const CONFIG = {
  // SOLO PARA PRUEBAS con el número de prueba de Meta (+1 555...):
  // Meta solo deja responder a números de la lista de prueba, y a veces el mensaje llega sin número.
  // Pon aquí tu celular de prueba. Cuando pases a tu número real, déjalo vacío: ''
  numeroPrueba: '51993862844',
  // Cada cuántas horas se vuelve a mandar la bienvenida larga a un mismo cliente
  horasEntreBienvenidas: 24,
  // Tras responder una opción, ¿volver a mandar el menú? (cada mensaje cuenta en tu cupo gratis)
  reenviarMenu: true,
  // Número de la asesora (el celular de la empresa), formato wa.me sin "+"
  linkAsesora: 'https://wa.me/51999999999',
  // Catálogos en PDF: deben ser links PÚBLICOS (Drive con "cualquiera con el enlace", S3, tu web)
  // titulo: máx. 24 caracteres | descripcion: máx. 72 | máximo 9 catálogos
  catalogos: [
    { titulo: 'Cumpleaños y Eventos', descripcion: 'Cumpleaños, eventos y disfraces', url: 'https://drive.usercontent.google.com/download?id=1IwQanzHMxXCgupzinLTR-kC9AZsOjnzm&export=download', nombre: 'UYAY Cumpleanos Eventos y Disfraces.pdf' },
    { titulo: 'Hogar y Manualidades', descripcion: 'Hogar, decoración y manualidades', url: 'https://drive.usercontent.google.com/download?id=1d5LG7uFemYe7eog0g-60zkIPEFwjbJQR&export=download', nombre: 'UYAY Hogar y Manualidades.pdf' },
    { titulo: 'Juguetería y TCG', descripcion: 'Juguetes y cartas coleccionables', url: 'https://drive.usercontent.google.com/download?id=1K7aEWZDpFK0b3keqh2qAx5pwz8aMJI5H&export=download', nombre: 'UYAY Jugueteria y TCG.pdf' },
    { titulo: 'Libros y Útiles', descripcion: 'Libros y útiles escolares', url: 'https://drive.usercontent.google.com/download?id=1z5ac8lvDUNH9nU76x16On49O8IFP2TKV&export=download', nombre: 'UYAY Libros y Utiles Escolares.pdf' },
    { titulo: 'Ropa', descripcion: 'Ropa y moda', url: 'https://drive.usercontent.google.com/download?id=1Zkmo9PMZAbAlUsJMyL11zVgV-k5cPzT5&export=download', nombre: 'UYAY Ropa.pdf' },
  ],
  // Número que recibe el resumen de cada pedido de figura 3D (ej. '51999999999').
  // Vacío = no se avisa a nadie. OJO: en pruebas debe estar en la lista de Meta, y en producción
  // ese número debe haberle escrito al bot en las últimas 24 h para que le lleguen los avisos.
  numeroAdmin: '51993862844',
};

const TEXTOS = {
  f3dInicio:
`🧊✨ *PEDIDO DE FIGURA 3D* ✨🧊

¡Hacemos tu figura personalizada! 💖
Envíanos *en un solo mensaje* (puede ser una foto con texto):

📸 *Foto de referencia* (personaje, persona, mascota, logo...)
📏 *Altura* que quieres (ej. 10 cm, 15 cm, 20 cm)
🎨 *Detalles*: colores, acabado, nombre o texto, cantidad y *para qué fecha* la necesitas

_Ejemplo: (foto) "Goku de 15 cm, pintado, para el 20 de diciembre"_

_(Escribe *0* para cancelar)_`,
  f3dFotoExtra: `📸 ¡Foto recibida! Ahora escríbenos la *altura* y los *detalles* de tu figura 👇`,
  f3dFotoAgregada: `📸 Foto agregada a tu pedido ✅`,
  f3dResumen: (p) =>
`✅ *¡PEDIDO RECIBIDO!* 🧊

📝 *Tu pedido:* ${p.descripcion || '(ver fotos)'}
📸 *Fotos:* ${p.medios.length}

Una asesora revisará tu pedido y te enviará la *cotización* por aquí muy pronto 💖`,
  f3dAdmin: (p, quien) =>
`🔔 *NUEVO PEDIDO FIGURA 3D*
👤 Cliente: ${quien}
📝 Pedido: ${p.descripcion || '(ver fotos)'}
📸 Fotos: ${p.medios.length} (abajo)`,
  bienvenida:
`👑💖 *¡BIENVENIDA A UYAY QUEEN!* 💖👑

Gracias por escribirnos ✨
Somos *IMPORTADORES MAYORISTAS* de accesorios, bisutería y novedades para tu negocio 🎀

🎀 *NOVEDADES CADA 15 DÍAS*
Siempre encontrarás modelos nuevos y en tendencia.

🔥 *35% DE DESCUENTO*
En todos los productos marcados con ▬

🚚 *ENVÍOS DIARIOS A TODO EL PERÚ*
Despachamos a la agencia de transporte que prefieras.

📦 *SIN COSTOS ADICIONALES*
✅ No cobramos embalaje
✅ No cobramos traslado a la agencia
Solo pagas tus productos (el flete de la agencia es aparte).

🛍️ *COMPRA MÍNIMA: S/99*

📍 [TU DIRECCIÓN]
🕙 Lunes a sábado, 10:00 a. m. – 7:00 p. m.`,

  menuCuerpo:
`👑 *UYAY | ATENCIÓN MAYORISTA*

¡Estamos felices de atenderte! 💕

¿En qué podemos ayudarte hoy?
Toca el botón y elige una opción 👇`,

  catalogos:
`👑💗 ¡Claro que sí, reina!

Te compartimos nuestros *CATÁLOGOS ACTUALIZADOS* ✨

🎀 Accesorios, bisutería, carteras, belleza y muchas novedades en tendencia.

💕 Se actualizan cada 15 días.

Toca el botón y elige cuál quieres ver 👇`,

  catalogoEnviado: (c) => `📖 Aquí tienes: *${c.titulo}* ✨`,

  ver3d:
`🧊 *MIRA NUESTROS PRODUCTOS EN 3D* ✨

Gíralos, acércalos y míralos como si los tuvieras en la mano 💖

Toca el botón y elige 👇`,

  modelo3dEnviado: (m) => `🧊 *${m.titulo}*

Ábrelo aquí y gíralo con el dedo 👉 ${m.link}`,

  comoComprar:
`🛍️ *¿CÓMO COMPRAR?*

1️⃣ Revisa el catálogo y anota los códigos que te gustan.
2️⃣ Envíanos tu lista a nuestra asesora.
3️⃣ Te confirmamos stock y total.
4️⃣ Pagas por Yape, Plin o transferencia.

💰 Compra mínima: *S/99*`,

  envios:
`🚚 *ENVÍOS A TODO EL PERÚ*

Despachamos todos los días a la agencia de transporte que prefieras (Shalom, Marvisur, Olva, etc.).

📦 No cobramos embalaje ni traslado a la agencia.
El flete de la agencia lo pagas al recoger.`,

  ubicacion:
`📍 *NUESTRA TIENDA*
[TU DIRECCIÓN]

🕙 Lunes a sábado, 10:00 a. m. – 7:00 p. m.

¡Te esperamos! 💖`,

  asesora:
`💬 ¡Con gusto te atiende una asesora!

Escríbenos aquí 👉 ${CONFIG.linkAsesora}`,
};

const MENU_OPCIONES = [
  { id: 'catalogos', title: 'Ver catálogos',        description: 'Catálogos actualizados cada 15 días' },
  { id: 'figura3d',  title: 'Pedido figura 3D',     description: 'Cuéntanos tu idea y te cotizamos' },
  { id: 'comprar',   title: 'Cómo comprar',         description: 'Compra mínima, pagos y pedidos' },
  { id: 'envios',    title: 'Envíos',               description: 'Envíos diarios a todo el Perú' },
  { id: 'ubicacion', title: 'Ubicación y horario',  description: 'Visítanos en tienda' },
  { id: 'asesora',   title: 'Hablar con asesora',   description: 'Te atiende una persona' },
];

// Palabras o números que el cliente puede escribir en vez de usar el botón
const ATAJOS = {
  '1': 'catalogos', 'catalogo': 'catalogos', 'catálogo': 'catalogos', 'catalogos': 'catalogos', 'catálogos': 'catalogos',
  '2': 'figura3d', '3d': 'figura3d', 'figura': 'figura3d', 'figura 3d': 'figura3d', 'pedido': 'figura3d',
  '3': 'comprar', 'precio': 'comprar', 'precios': 'comprar', 'comprar': 'comprar',
  '4': 'envios', 'envio': 'envios', 'envío': 'envios', 'envios': 'envios', 'envíos': 'envios',
  '5': 'ubicacion', 'direccion': 'ubicacion', 'dirección': 'ubicacion', 'ubicacion': 'ubicacion', 'horario': 'ubicacion',
  '6': 'asesora', 'asesora': 'asesora', 'asesor': 'asesora', 'humano': 'asesora',
};

// =====================================================
//  LÓGICA (normalmente no necesitas tocar esto)
// =====================================================
const base = (to) => (/^[A-Z]{2}\./.test(to) ? { messaging_product: 'whatsapp', recipient: to } : { messaging_product: 'whatsapp', recipient_type: 'individual', to });
const texto = (to, body) => ({ ...base(to), type: 'text', text: { body, preview_url: true } });
const documento = (to, c) => ({ ...base(to), type: 'document', document: { link: c.url, filename: c.nombre } });
const video = (to, link, caption) => ({ ...base(to), type: 'video', video: { link, caption } });
const lista = (to, cuerpo, boton, tituloSeccion, filas) => ({
  ...base(to),
  type: 'interactive',
  interactive: {
    type: 'list',
    body: { text: cuerpo },
    action: { button: boton, sections: [{ title: tituloSeccion, rows: filas }] },
  },
});
const corta = (t, n) => (t || '').slice(0, n);
const submenuCatalogos = (to) => lista(to, TEXTOS.catalogos, 'Elegir catálogo', 'Catálogos',
  [
    ...CONFIG.catalogos.slice(0, 9).map((c, i) => ({ id: `cat_${i}`, title: corta(c.titulo, 24), description: corta(c.descripcion, 72) })),
    { id: 'cat_todos', title: 'Todos los catálogos', description: 'Te enviamos todos los PDF' },
  ]);
const submenu3d = (to) => lista(to, TEXTOS.ver3d, 'Elegir producto', 'En 3D',
  CONFIG.modelos3d.slice(0, 10).map((m, i) => ({ id: `m3d_${i}`, title: corta(m.titulo, 24), description: corta(m.descripcion, 72) })));
const enviar3d = (to, m) => {
  const out = [];
  if (m.video) out.push(video(to, m.video, `🎥 ${m.titulo}`));
  out.push(texto(to, TEXTOS.modelo3dEnviado(m)));
  return out;
};

const menu = (to) => ({
  ...base(to),
  type: 'interactive',
  interactive: {
    type: 'list',
    body: { text: TEXTOS.menuCuerpo },
    action: {
      button: 'Ver opciones',
      sections: [{ title: 'Menú UYAY', rows: MENU_OPCIONES }],
    },
  },
});

// Encuentra el objeto "value" del webhook sin importar cómo lo entregue el trigger
function getValue(j) {
  if (j.messages || j.statuses) return j;
  return j?.entry?.[0]?.changes?.[0]?.value
      || j?.body?.entry?.[0]?.changes?.[0]?.value
      || {};
}

const memoria = $getWorkflowStaticData('global'); // funciona con el flujo ACTIVADO
memoria.vistos = memoria.vistos || {};

const salida = [];
for (const item of $input.all()) {
  const value = getValue(item.json);
  const msg = value.messages?.[0];
  if (!msg) continue; // ignora notificaciones de "entregado/leído"

  const phoneNumberId = value.metadata?.phone_number_id;
  const to = msg.from || value.contacts?.[0]?.wa_id || CONFIG.numeroPrueba || msg.from_user_id || value.contacts?.[0]?.user_id;
  const payloads = [];

  // ---------- Pedido de figura 3D (conversación por pasos) ----------
  memoria.f3d = memoria.f3d || {};
  const uid = msg.from_user_id || msg.from || to;
  const txtLibre = msg.type === 'text' ? (msg.text?.body || '').trim() : '';
  const esMedio = ['image', 'video', 'document', 'audio'].includes(msg.type);
  const pedido = memoria.f3d[uid];
  if (pedido && (msg.type === 'interactive' || ['0', 'menu', 'menú', 'cancelar'].includes(txtLibre.toLowerCase()))) {
    delete memoria.f3d[uid]; // canceló o tocó el menú: sigue el flujo normal
  } else if (pedido && pedido.paso === 'enviado') {
    // Ya se envió el pedido: fotos extra en los siguientes 15 min se agregan al pedido
    if (esMedio && Date.now() - pedido.t < 15 * 60 * 1000) {
      payloads.push(texto(to, TEXTOS.f3dFotoAgregada));
      if (CONFIG.numeroAdmin) {
        payloads.push(texto(CONFIG.numeroAdmin, `📸 Foto extra del pedido de ${pedido.quien}`));
        payloads.push({ ...base(CONFIG.numeroAdmin), type: msg.type, [msg.type]: { id: msg[msg.type]?.id } });
      }
      for (const p of payloads) salida.push({ json: { phone_number_id: phoneNumberId, payload: p } });
      continue;
    }
    delete memoria.f3d[uid]; // pasó el tiempo o escribió otra cosa: flujo normal
  } else if (pedido) {
    if (esMedio) pedido.medios.push({ tipo: msg.type, id: msg[msg.type]?.id });
    const textoPedido = txtLibre || msg[msg.type]?.caption || '';
    if (textoPedido) {
      pedido.descripcion = textoPedido;
      pedido.quien = `${value.contacts?.[0]?.profile?.name || 'Cliente'} (${msg.from || msg.from_user_id})`;
      payloads.push(texto(to, TEXTOS.f3dResumen(pedido)));
      if (CONFIG.numeroAdmin) {
        payloads.push(texto(CONFIG.numeroAdmin, TEXTOS.f3dAdmin(pedido, pedido.quien)));
        for (const m of pedido.medios) if (m.id) payloads.push({ ...base(CONFIG.numeroAdmin), type: m.tipo, [m.tipo]: { id: m.id } });
      }
      pedido.paso = 'enviado'; pedido.t = Date.now();
      payloads.push(menu(to));
    } else {
      payloads.push(texto(to, esMedio ? TEXTOS.f3dFotoExtra : TEXTOS.f3dInicio));
    }
    for (const p of payloads) salida.push({ json: { phone_number_id: phoneNumberId, payload: p } });
    continue;
  }

  // ¿Qué eligió el cliente?
  let opcion = null;
  if (msg.type === 'interactive') {
    opcion = msg.interactive?.list_reply?.id || msg.interactive?.button_reply?.id || null;
  } else if (msg.type === 'text') {
    const t = (msg.text?.body || '').trim().toLowerCase();
    opcion = ATAJOS[t] || null;
  }

  let fin = true; // ¿reenviar el menú principal al final?
  if (opcion && opcion.startsWith('cat_')) {
    const elegidos = opcion === 'cat_todos' ? CONFIG.catalogos : [CONFIG.catalogos[Number(opcion.slice(4))]].filter(Boolean);
    for (const c of elegidos) {
      payloads.push(texto(to, TEXTOS.catalogoEnviado(c)));
      payloads.push(documento(to, c));
    }
    opcion = 'enviado';
  } else if (opcion && opcion.startsWith('m3d_')) {
    const m = CONFIG.modelos3d[Number(opcion.slice(4))];
    if (m) payloads.push(...enviar3d(to, m));
    opcion = 'enviado';
  }

  switch (opcion) {
    case 'enviado': break;
    case 'catalogos': payloads.push(submenuCatalogos(to)); fin = false; break;
    case 'figura3d':  memoria.f3d[uid] = { paso: 'esperando', medios: [], descripcion: '' }; payloads.push(texto(to, TEXTOS.f3dInicio)); fin = false; break;
    case 'comprar':   payloads.push(texto(to, TEXTOS.comoComprar)); break;
    case 'envios':    payloads.push(texto(to, TEXTOS.envios)); break;
    case 'ubicacion': payloads.push(texto(to, TEXTOS.ubicacion)); break;
    case 'asesora':   payloads.push(texto(to, TEXTOS.asesora)); break;
    default: {
      // Mensaje libre (hola, foto, audio...): bienvenida si toca + menú
      const ahora = Date.now();
      const ultimo = memoria.vistos[to] || 0;
      if (ahora - ultimo > CONFIG.horasEntreBienvenidas * 3600 * 1000) {
        payloads.push(texto(to, TEXTOS.bienvenida));
      }
      memoria.vistos[to] = ahora;
      payloads.push(menu(to));
    }
  }

  if (opcion && fin && opcion !== 'asesora' && CONFIG.reenviarMenu) payloads.push(menu(to));

  for (const p of payloads) salida.push({ json: { phone_number_id: phoneNumberId, payload: p } });
}

return salida;
